import{_ as e,c as r,o as i,ah as t}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"7、【師】 坎下坤上","description":"溫公易說 - 7、【師】 坎下坤上","frontmatter":{"title":"7、【師】 坎下坤上","description":"溫公易說 - 7、【師】 坎下坤上"},"headers":[],"relativePath":"classics/wengong/008.md","filePath":"classics/wengong/008.md"}'),n={name:"classics/wengong/008.md"};function l(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="_7、【師】-坎下坤上" tabindex="-1">7、【師】 坎下坤上 <a class="header-anchor" href="#_7、【師】-坎下坤上" aria-label="Permalink to “7、【師】 坎下坤上”">​</a></h1><p>師：貞，丈人吉，無咎。何也？曰：難之也。夫治眾，天下之大事也，非聖人則不能。夫眾之所服者，武也；所從者，智也；所親者，仁也。三者不備而能用其眾，未之有也。然或得之小，或得之大；或用之邪，或用之正。邪正大小之道，其得失吉凶相去遠矣。彼小人者，以矯矯為武，瞲瞲為智，喣喣為仁，眾人亦有悅而從之者，所謂小也。聖人者，以正人為武，安人為智，利人為仁，天下皆悅而從之，所謂大也。夫小人之得眾也，以為上則以為下，則亂，故謂之邪。聖人之得眾也，所以禁而止亂也，故謂之正。夫眾非小人之所用也，小人用之以為不正，咎孰大焉。</p><p>子罕曰：兵者，所以威不軌而昭文德也。聖人以興，亂人以廢，此之謂也。</p><h3 id="彖曰-師眾也-貞正也。能以眾正-可以王矣。剛中而應-行險而順-以此毒天下而民從之-吉又何咎矣。王者-何大人之謂也-剛中而應-行險而順者-治眾而不以剛則慢而不振-用剛而不獲中則暴而無親。上無應於君-下無應於民-則身危而功不成。所施不在於順-則眾怒而民不從。四者非所以吉而無咎也。吉而無咎-則惟剛中而應-行險而順者乎-夫兵者-危事也-故曰行險。財用之蠹-而民之殘也-故曰毒天下。毒之者-其志將以安之也-若針砭之所以已疾也-是以民從而無咎也。" tabindex="-1">彖曰：師眾也，貞正也。能以眾正，可以王矣。剛中而應，行險而順，以此毒天下而民從之，吉又何咎矣。王者，何大人之謂也？剛中而應，行險而順者，治眾而不以剛則慢而不振，用剛而不獲中則暴而無親。上無應於君，下無應於民，則身危而功不成。所施不在於順，則眾怒而民不從。四者非所以吉而無咎也。吉而無咎，則惟剛中而應，行險而順者乎？夫兵者，危事也，故曰行險。財用之蠹，而民之殘也，故曰毒天下。毒之者，其志將以安之也，若針砭之所以已疾也，是以民從而無咎也。 <a class="header-anchor" href="#彖曰-師眾也-貞正也。能以眾正-可以王矣。剛中而應-行險而順-以此毒天下而民從之-吉又何咎矣。王者-何大人之謂也-剛中而應-行險而順者-治眾而不以剛則慢而不振-用剛而不獲中則暴而無親。上無應於君-下無應於民-則身危而功不成。所施不在於順-則眾怒而民不從。四者非所以吉而無咎也。吉而無咎-則惟剛中而應-行險而順者乎-夫兵者-危事也-故曰行險。財用之蠹-而民之殘也-故曰毒天下。毒之者-其志將以安之也-若針砭之所以已疾也-是以民從而無咎也。" aria-label="Permalink to “彖曰：師眾也，貞正也。能以眾正，可以王矣。剛中而應，行險而順，以此毒天下而民從之，吉又何咎矣。王者，何大人之謂也？剛中而應，行險而順者，治眾而不以剛則慢而不振，用剛而不獲中則暴而無親。上無應於君，下無應於民，則身危而功不成。所施不在於順，則眾怒而民不從。四者非所以吉而無咎也。吉而無咎，則惟剛中而應，行險而順者乎？夫兵者，危事也，故曰行險。財用之蠹，而民之殘也，故曰毒天下。毒之者，其志將以安之也，若針砭之所以已疾也，是以民從而無咎也。”">​</a></h3><h3 id="象曰-地中有水-師。君子以容民畜眾。" tabindex="-1">象曰：地中有水，師。君子以容民畜眾。 <a class="header-anchor" href="#象曰-地中有水-師。君子以容民畜眾。" aria-label="Permalink to “象曰：地中有水，師。君子以容民畜眾。”">​</a></h3><p>師之所以為容民畜眾者，非特施於治兵之謂也。故天子用之以治天下，諸侯用之以治其國，卿大夫用之以治其家，其道一也。</p><h3 id="初六-師出以律-否臧兇。-象曰-師出以律-失律兇也。" tabindex="-1">初六：師出以律，否臧兇。 象曰：師出以律，失律兇也。 <a class="header-anchor" href="#初六-師出以律-否臧兇。-象曰-師出以律-失律兇也。" aria-label="Permalink to “初六：師出以律，否臧兇。 象曰：師出以律，失律兇也。”">​</a></h3><h3 id="九二-在師中-吉無咎-王三錫命。-象曰-在師中-吉承天寵也。王三錫命-懷萬邦也。" tabindex="-1">九二：在師中，吉無咎，王三錫命。 象曰：在師中，吉承天寵也。王三錫命，懷萬邦也。 <a class="header-anchor" href="#九二-在師中-吉無咎-王三錫命。-象曰-在師中-吉承天寵也。王三錫命-懷萬邦也。" aria-label="Permalink to “九二：在師中，吉無咎，王三錫命。 象曰：在師中，吉承天寵也。王三錫命，懷萬邦也。”">​</a></h3><h3 id="六三-師或輿尸-兇。-象曰-師或輿尸-大無功也。" tabindex="-1">六三：師或輿尸，兇。 象曰：師或輿尸，大無功也。 <a class="header-anchor" href="#六三-師或輿尸-兇。-象曰-師或輿尸-大無功也。" aria-label="Permalink to “六三：師或輿尸，兇。 象曰：師或輿尸，大無功也。”">​</a></h3><h3 id="六四-師左次-無咎。-象曰-左次無咎-未失常也。" tabindex="-1">六四：師左次，無咎。 象曰：左次無咎，未失常也。 <a class="header-anchor" href="#六四-師左次-無咎。-象曰-左次無咎-未失常也。" aria-label="Permalink to “六四：師左次，無咎。 象曰：左次無咎，未失常也。”">​</a></h3><h3 id="六五-田有禽-利執言-無咎。長子帥師-弟子輿尸-貞兇。-象曰-長子帥師-以中行也。弟子輿尸-使不當也。" tabindex="-1">六五：田有禽，利執言，無咎。長子帥師，弟子輿尸，貞兇。 象曰：長子帥師，以中行也。弟子輿尸，使不當也。 <a class="header-anchor" href="#六五-田有禽-利執言-無咎。長子帥師-弟子輿尸-貞兇。-象曰-長子帥師-以中行也。弟子輿尸-使不當也。" aria-label="Permalink to “六五：田有禽，利執言，無咎。長子帥師，弟子輿尸，貞兇。 象曰：長子帥師，以中行也。弟子輿尸，使不當也。”">​</a></h3><p>師六五柔也，其為師之主奈何？古者人君之遣將也，跪而推轂曰：&quot;閫以內，寡人制之；閫以外，將軍制之。&quot;進止之制，賞罰之權，皆決於外，不從中覆也。委任責成功而已矣。六五以柔居尊，下應於二，二以剛中能任其事，是以動則有功，若田狩而獲禽也。師出無名，事故不成，故曰利執言。執者何？奉辭伐罪之謂也。舉國家之眾而委之一人，此安危之機，存亡之端，不可以不謹。謹擇其人，是人君之事守也。故曰長子帥師，弟子輿尸，貞兇者，雖正猶兇也。</p><h3 id="上六-大君有命-開國承家-小人勿用。-象曰-大君有命-以正功也。小人勿用-必亂邦也。" tabindex="-1">上六：大君有命，開國承家，小人勿用。 象曰：大君有命，以正功也。小人勿用，必亂邦也。 <a class="header-anchor" href="#上六-大君有命-開國承家-小人勿用。-象曰-大君有命-以正功也。小人勿用-必亂邦也。" aria-label="Permalink to “上六：大君有命，開國承家，小人勿用。 象曰：大君有命，以正功也。小人勿用，必亂邦也。”">​</a></h3>',13)])])}const b=e(n,[["render",l]]);export{p as __pageData,b as default};
